CREATE TABLE public.group2_rule_map (rule_id text PRIMARY KEY, original_wording text NOT NULL, method text NOT NULL, default_priority text NOT NULL, validation_boundary text NOT NULL, original_record jsonb NOT NULL);
GRANT SELECT ON public.group2_rule_map TO authenticated;
GRANT ALL ON public.group2_rule_map TO service_role;
ALTER TABLE public.group2_rule_map ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff read group2 rule map" ON public.group2_rule_map FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'reviewer'));
CREATE TABLE public.group2_interface_fields (field_key text PRIMARY KEY, layer text NOT NULL, field_name text NOT NULL, type_values text NOT NULL, group2_use text NOT NULL, position integer NOT NULL, original_record jsonb NOT NULL);
GRANT SELECT ON public.group2_interface_fields TO authenticated;
GRANT ALL ON public.group2_interface_fields TO service_role;
ALTER TABLE public.group2_interface_fields ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff read group2 interface" ON public.group2_interface_fields FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'reviewer'));
CREATE TABLE public.group2_decision_map (decision text PRIMARY KEY, ui_label text NOT NULL, show_explanation text NOT NULL, next_action text NOT NULL, group3_processing text NOT NULL, original_record jsonb NOT NULL);
GRANT SELECT ON public.group2_decision_map TO authenticated;
GRANT ALL ON public.group2_decision_map TO service_role;
ALTER TABLE public.group2_decision_map ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff read group2 decision map" ON public.group2_decision_map FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'reviewer'));
CREATE TABLE public.group2_acceptance_tests (test_id text PRIMARY KEY, criterion text NOT NULL, expected text NOT NULL, owner text NOT NULL, review_status text NOT NULL, execution_status text NOT NULL DEFAULT 'not_executed', original_record jsonb NOT NULL);
GRANT SELECT ON public.group2_acceptance_tests TO authenticated;
GRANT ALL ON public.group2_acceptance_tests TO service_role;
ALTER TABLE public.group2_acceptance_tests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff read group2 acceptance" ON public.group2_acceptance_tests FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'reviewer'));
ALTER TABLE public.test_cases ADD COLUMN import_bundle text, ADD COLUMN original_record jsonb;
ALTER TABLE public.evaluations ADD COLUMN execution_kind text NOT NULL DEFAULT 'simulated_candidate', ADD COLUMN execution_trace jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN expected_decision_snapshot text;
COMMENT ON COLUMN public.evaluations.execution_kind IS 'deterministic_rule, simulated_candidate, or external_model_unavailable; never a live model claim.';
COMMENT ON TABLE public.group2_rule_map IS 'Original Group 1 rubric wording from Group 2 workbook; mappings are not clinical approval or executable predicates.';
COMMENT ON TABLE public.group2_acceptance_tests IS 'Proposed acceptance criteria, not imported execution results or clinical validation.';